230: bool CImage::ProcessMessage( const SEvent &sEvent )
231: {
232: 	if ( sEvent.nEvent == EVENT_TEMPLATECREATE )
233: 	{
234: 		NGfx::SPixel8888 sColor;
235: 		sColor.color = sEvent.pControl->nColor;
236: 		SetColor( sColor );
237: 		SetImage( sEvent.pControl->pTextures[0] );
238: 	}
239: 
240: 	return CWindow::ProcessMessage( sEvent );
241: }
